subtopics.example:
# vague: model can't tell when to use it
{"name": "handle", "description": "Handles stuff."}

# clear: verb + noun + when-to-use + argument hints
{
    "name": "search_orders",
    "description": "Find a customer's orders by email. Use when the "
                   "user asks about order status or history.",
    "parameters": {"email": {"type": "string",
                             "description": "customer email, e.g. a@b.com"}},
}

# unsafe: a retry charges the customer twice
def charge(amount):
    payments.create(amount=amount)

# safe: idempotency key makes a repeat call a no-op
def charge(amount, idempotency_key):
    # provider returns the SAME charge for a repeated key
    return payments.create(amount=amount, idempotency_key=idempotency_key)
# now the agent can safely retry without double-billing

# dangerous: model can run ANY query, including DROP TABLE
{"name": "run_sql", "parameters": {"query": {"type": "string"}}}

# least privilege: only the read the agent actually needs
def get_customer_email(customer_id: str) -> str:
    # parameterized, read-only, single table, no arbitrary SQL
    row = db.execute(
        "SELECT email FROM customers WHERE id = ?", (customer_id,)
    ).fetchone()
    return row["email"] if row else ""

# noisy: dumps everything, floods the context window
def search(q):
    return db.full_dump(q)   # thousands of rows, every column

# tight: only what the model needs, capped and summarized
def search(q, limit=5):
    rows = db.query(q, limit=limit)
    return {
        "count": len(rows),
        "results": [{"id": r.id, "title": r.title} for r in rows],
    }  # small, stable, easy for the model to reason over
